int main() {
    std::string fancy_text = "Hello *world_ and *everyone! ";
    std::string html_text = convertToHtml(fancy_text);
    std::cout << html_text << std::endl; // Output: "<em>Hello </em><strong>world</strong> <em> and </em><strong>everyone</strong>!"
    return 0;
}
```

